CREATE OR REPLACE FUNCTION public.finance_can_merge_accounts(t uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.user_has_tenant(auth.uid(),t) AND (public.finance_schedule_manager(t) OR EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=t AND user_id=auth.uid() AND role='accountant') OR EXISTS(SELECT 1 FROM public.user_access_control a JOIN public.user_page_permissions p ON p.user_id=a.user_id AND p.tenant_id=a.tenant_id WHERE a.tenant_id=t AND a.user_id=auth.uid() AND a.status='active' AND a.position='finance' AND p.page_key='finance' AND p.can_access AND p.authority IN('edit','admin') AND NOT('finance.post_journal'=ANY(p.hidden_actions)))); $$;
REVOKE ALL ON FUNCTION public.finance_can_merge_accounts(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.finance_can_merge_accounts(uuid) TO authenticated;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.finance_account_merge(uuid,uuid,uuid,date,boolean)'::regprocedure) INTO def; IF position('IF NOT finance_schedule_manager(t)' IN def)=0 THEN RAISE EXCEPTION 'Merge authorization anchor unavailable'; END IF; def:=replace(def,'IF NOT finance_schedule_manager(t)','IF NOT finance_can_merge_accounts(t)'); def:=replace(def,'Owner or admin required','Owner, admin or authorized accountant required'); EXECUTE def;
SELECT pg_get_functiondef('public.finance_sales_deferred_save(uuid,jsonb)'::regprocedure) INTO def;
IF position('IF abs(remain-coalesce' IN def)=0 OR position('Card tips require the existing receipt review flow' IN def)=0 THEN RAISE EXCEPTION 'Deferred tips anchors unavailable';END IF;
def:=replace(def,'IF abs(remain-coalesce','IF coalesce((p->>''cardTips'')::numeric,0)>0 OR abs(coalesce((p->>''cardTips'')::numeric,0))<>round(abs(coalesce((p->>''cardTips'')::numeric,0)),2) THEN RAISE EXCEPTION ''Card tips must be a negative cents deduction included in card tenders'';END IF; IF abs(remain-abs(coalesce((p->>''cardTips'')::numeric,0))-coalesce');
def:=replace(def,'IF amt>0 THEN RAISE EXCEPTION ''Card tips require the existing receipt review flow; deferred draft not saved'';END IF;','IF amt>0 THEN IF tip IS NULL OR NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE tenant_id=t AND id=tip AND is_active AND account_type=''liability'') OR amt>coalesce((p->>''visa'')::numeric,0)+coalesce((p->>''mastercard'')::numeric,0)+coalesce((p->>''amex'')::numeric,0)+coalesce((p->>''unionPay'')::numeric,0)+coalesce((p->>''jcb'')::numeric,0) THEN RAISE EXCEPTION ''Tips payable venue mapping and sufficient card tenders required'';END IF;ls:=ls||jsonb_build_array(jsonb_build_object(''account_id'',tip,''debit'',0,''credit'',amt,''venue'',v,''memo'',''Card tips payable''));END IF;');
def:=replace(def,',0,p->>''receiptFileUrl'',p->>''receiptFileName''',',-abs(coalesce((p->>''cardTips'')::numeric,0)),p->>''receiptFileUrl'',p->>''receiptFileName''');EXECUTE def;END $$;